  "settings.clearLibraryV2Hint": "Apaga o índice (faixas, álbuns, artistas). Perdem-se junto: o conteúdo das playlists, as avaliações, os marcadores, os favoritos, os box sets montados manualmente e as edições de álbuns. Nenhum arquivo de música é excluído. Um backup do banco de dados é feito logo antes. Uma varredura só traz de volta as faixas. Para atualizar a biblioteca, prefira uma varredura completa: ela mantém os box sets e as edições de álbuns.",
