  "renderer.depthCapNotRate": "Atenção: limitar a profundidade de bits não limita a taxa de amostragem. Um arquivo de 96 kHz/24 bits vira 96 kHz/16 bits — ainda em 96 kHz. Se o seu renderizador vai no máximo até 48 kHz, defina também a “Taxa máx.”.",
