  "renderer.resetCompat": "Redefinir compatibilidade",
  "renderer.resetCompatHint": "Depois que este renderizador recusa um comando, o Tune memoriza a forma de comando que ele aceitou e a reutiliza, mesmo após uma reinicialização. Redefinir faz a próxima faixa começar de novo pelo comando completo.",
