  "settings.dlnaCap16bitHint": "Ative se o hi-res (24 bits) fica mudo neste renderizador enquanto o 16 bits funciona (Ruark R3). Recodifica para FLAC 16 bits em vez de enviar 24 bits direto que o renderizador não decodifica.",
  "settings.alacPassthroughHint": "Enviar ALAC como está para este renderizador (bit-perfect, sem transcodificação para FLAC). Ative somente se o renderizador decodificar ALAC nativamente; caso contrário, não haverá som.",
  "settings.aacPassthroughHint": "Enviar AAC como está para este renderizador em vez de transcodificá-lo para FLAC. A fonte já tem perdas, então a transcodificação não acrescenta qualidade — só atrasa o primeiro som. Ative somente se o renderizador decodificar AAC nativamente; caso contrário, não haverá som.",
  "settings.hqplayerHint": "Conecte o Tune ao HQPlayer para upsampling e filtros audiófilos. Porta padrão: 4321 (v4/v5) ou 8019 (v6).",
