  "settings.cloudDisconnected": "Desconectado da nuvem",
  "settings.signOutConfirm": "Sair da sua conta Mozaiklabs? Este servidor será desvinculado da conta: a cópia online da biblioteca e os compartilhamentos do Tune Circle serão removidos, e os recursos premium vindos da conta deixarão de funcionar (uma chave de licença continua ativa). Você poderá entrar de novo depois.",
  "settings.licenseRateLimited": "Tentativas demais — aguarde um minuto antes de tentar novamente.",
  "settings.cloudComingSoon": "Nuvem em breve neste servidor",
  "settings.telemetry": "Telemetria",
  "settings.telemetryHint": "Enviar estatísticas de uso para melhorar o Tune: identificador da instância, versão, plataforma, tamanhos da biblioteca, serviços conectados e modelos de dispositivos.",
  "settings.telemetryOffScope": "Desativá-la também interrompe o compartilhamento e o download de metadados da comunidade. A validação da licença continua funcionando, então o Premium nunca é perdido.",
  "settings.communitySync": "Compartilhamento de metadados com a comunidade",
  "settings.communitySyncHint": "Participar do enriquecimento comunitário: resolução MusicBrainz, gêneros e créditos (compositor, regente, intérpretes) compartilhados entre servidores Tune. Anônimo — nunca seus arquivos.",
  "settings.cloudListens": "Enviar minhas audições para minha conta",
  "settings.cloudListensHint": "Adiciona as audições deste servidor à página “Minhas audições” da sua conta, junto com as dos seus outros servidores Tune. Para cada audição: a data, a duração, um identificador de perfil opaco, o título, o artista, o álbum e, quando conhecidos, o ISRC e o identificador MusicBrainz. Nunca seus caminhos de arquivo, seu endereço IP ou os nomes das suas zonas. Desativado por padrão.",
  "settings.cloudListensLink": "Ver minhas audições no mozaiklabs.fr",
  "settings.cloudListensConsentTitle": "Compartilhar suas audições com sua conta mozaiklabs.fr?",
  "settings.cloudListensConsentIntro": "O Tune pode adicionar as audições deste servidor à sua conta mozaiklabs.fr. Nada é enviado até você responder.",
  "settings.cloudListensConsentSentLabel": "O que é enviado:",
  "settings.cloudListensConsentSent": "para cada audição, a data, a duração, o título, o artista, o álbum, um identificador de perfil opaco e, quando conhecidos, os identificadores ISRC e MusicBrainz.",
  "settings.cloudListensConsentNeverLabel": "O que nunca é enviado:",
  "settings.cloudListensConsentNever": "seus caminhos de arquivo, seu endereço IP, os nomes das suas zonas e os nomes dos seus perfis.",
  "settings.cloudListensConsentBenefit": "O que você ganha: a página “Minhas audições”, que reúne as audições de todos os seus servidores Tune, e as audições da comunidade.",
  "settings.cloudListensConsentSettingsReminder": "Você pode mudar de ideia a qualquer momento em Configurações › Sistema.",
  "settings.cloudListensConsentError": "Não foi possível salvar sua resposta. Tente novamente.",
  "settings.cloudListensConsentNo": "Não",
  "settings.cloudListensConsentYes": "Sim, compartilhar",
  "settings.cloudListensConsentClose": "Fechar sem responder",
  "settings.communityShare": "Compartilhar minhas avaliações e audições com a comunidade (anonimamente)",
  "settings.communityShareHint": "Separado de “Minhas audições” e desativado por padrão. Suas avaliações de álbuns (sem comentário) e as audições que sua conta recebe DEPOIS da ativação entram em totais públicos e anônimos, exibidos na página de um álbum a partir de três pessoas distintas. Nenhum dado individual é exibido. Desativar remove sua contribuição imediatamente.",
  "settings.communityMeasuresReceive": "Receber resultados de análise da comunidade",
  "settings.communityMeasuresReceiveHint": "Desativado por padrão. Para seus arquivos FLAC, o servidor pede ao mozaiklabs.fr ReplayGain, faixa dinâmica e impressões digitais acústicas já medidos exatamente no mesmo sinal por pelo menos duas outras instalações. Eles só preenchem o que falta: suas tags e suas próprias medições nunca são substituídas. O site só recebe um prefixo curto, nunca a lista dos seus arquivos.",
  "settings.communityMeasuresContribute": "Compartilhar meus resultados de análise com a comunidade",
  "settings.communityMeasuresContributeHint": "Desativado por padrão. O servidor envia ao site apenas as medições que ele próprio fez nos seus arquivos FLAC (ReplayGain, faixa dinâmica, impressão digital acústica), identificadas pela assinatura do sinal. Nenhum caminho, título, nome de arquivo ou conta é enviado: o servidor se identifica pelo número de instalação. Desativar apaga o que foi enviado.",
