  "cloudBackup.title": "Backup na nuvem",
  "cloudBackup.intro": "O Tune faz backup das suas personalizações na Mozaiklabs, criptografadas neste servidor com uma chave que a Mozaiklabs não conhece: configurações, zonas, perfis e preferências, equalizadores, favoritos, playlists e rádios. Nunca sua biblioteca, nem as senhas e tokens dos serviços, com uma exceção: o token do Discogs, que viaja criptografado com o resto. São mantidos no máximo três snapshots por máquina e cinco máquinas por conta; os mais antigos são removidos.",
