  "v2.xtc.eyebrow": "Caixas de som · Premium",
  "v2.xtc.speakersOnly": "Processamento para caixas de som; nunca em fones de ouvido.",
  "v2.xtc.speakersOnlyNote": "Em fones de ouvido, este processamento faz o contrário do crossfeed: ele colore o som sem melhorar nada. Não use em uma zona de fones, nem junto com o Crossfeed Pro na mesma zona.",
  "v2.xtc.monoNote": "A compatibilidade mono não é garantida: o centro também é filtrado.",
