  "v2.xtc.gainCeiling": "Teto de ganho nas caixas de som (dB)",
  "v2.xtc.gainCeilingNote": "Limita o reforço que o processamento pode impor às caixas de som. Um teto baixo protege os alto-falantes e colore menos, mas limita a separação.",
