  "upsampling.eyebrow": "Plugin Premium",
  "upsampling.title": "Upsampling",
  "upsampling.lead": "Eleva a taxa da fonte para a taxa mais alta que o DAC aceita, seguindo a família dela (44,1 → 352,8 kHz, 48 → 384 kHz), na saída local. O nível é reduzido em 3 dB, e um limitador de segurança segura os raros picos restantes: sem clipping.",
