  "upsampling.filterHint": "Só são oferecidos os filtros que esta máquina roda em tempo real (com margem de ×3). Entre parênteses: a redução de nível.",
  "upsampling.filterNotAdmitted": "Esta máquina não roda este filtro em tempo real: ele não será aplicado. Escolha outro ou meça a máquina de novo.",
  "upsampling.target": "Taxa alvo",
  "upsampling.targetHint": "Um múltiplo inteiro da fonte, nunca além do que o DAC aceita.",
  "upsampling.targetMax": "Máximo do DAC",
  "upsampling.dither": "Dither",
  "upsampling.ditherHint": "O da própria saída, na redução de profundidade: TPDF, sem noise shaping.",
  "upsampling.machine": "Teste da máquina",
